import { createContext, useContext, useState, type ReactNode } from 'react'

export type Item = { id: string; name: string; price: number }

type CartContextValue = {
  items: Item[]
  addItem: (item: Item) => void
  removeItem: (id: string) => void
}

const CartContext = createContext<CartContextValue | null>(null)

export function CartProvider({ children }: { children: ReactNode }) {
  const [items, setItems] = useState<Item[]>([])

  const addItem = (item: Item) => setItems([...items, item])
  const removeItem = (id: string) => setItems(items.filter((i) => i.id !== id))

  return (
    <CartContext value={{ items, addItem, removeItem }}>
      {children}
    </CartContext>
  )
}

export function useCart() {
  const cart = useContext(CartContext)
  if (cart === null) throw new Error('useCart needs a CartProvider')
  return cart
}

import { memo } from 'react'
import { useCart, type Item } from '../cart/CartProvider'

export const ProductCard = memo(function ProductCard({ item }: { item: Item }) {
  const { addItem } = useCart()
  return (
    <li>
      {item.name}
      <button onClick={() => addItem(item)}>Add</button>
    </li>
  )
})

