import { createContext, useCallback, useContext, useMemo, useState, type ReactNode } from 'react'

export type Item = { id: string; name: string; price: number }

type CartContextValue = {
  items: Item[]
  addItem: (item: Item) => void
  removeItem: (id: string) => void
}

const CartContext = createContext<CartContextValue | null>(null)

export function CartProvider({ children }: { children: ReactNode }) {
  const [items, setItems] = useState<Item[]>([])

  const addItem = useCallback((item: Item) => setItems([...items, item]), [items])
  const removeItem = useCallback(
    (id: string) => setItems(items.filter((i) => i.id !== id)),
    [items],
  )

  const value = useMemo(
    () => ({ items, addItem, removeItem }),
    [items, addItem, removeItem],
  )

  return <CartContext value={value}>{children}</CartContext>
}

import { createContext, useContext, useMemo, useState, type ReactNode } from 'react'

export type Item = { id: string; name: string; price: number }

type CartActions = {
  addItem: (item: Item) => void
  removeItem: (id: string) => void
}

const ItemsContext = createContext<Item[] | null>(null)
const ActionsContext = createContext<CartActions | null>(null)

export function CartProvider({ children }: { children: ReactNode }) {
  const [items, setItems] = useState<Item[]>([])

  const actions = useMemo<CartActions>(
    () => ({
      addItem: (item) => setItems((prev) => [...prev, item]),
      removeItem: (id) => setItems((prev) => prev.filter((i) => i.id !== id)),
    }),
    [],
  )

  return (
    <ActionsContext value={actions}>
      <ItemsContext value={items}>{children}</ItemsContext>
    </ActionsContext>
  )
}

export function useCartItems() {
  const items = useContext(ItemsContext)
  if (items === null) throw new Error('useCartItems needs a CartProvider')
  return items
}

export function useCartActions() {
  const actions = useContext(ActionsContext)
  if (actions === null) throw new Error('useCartActions needs a CartProvider')
  return actions
}
